Ltac tab_now FTI AC ACC MU WM FW TAC :=
  lazymatch goal with |- evt _ _ (MS _ _ _ _ _ ?mc _) =>
    lazymatch type of MU with munch _ _ mc =>
      let FI2 := fresh "FIc" in let AC2 := fresh "ACc" in let ACC2 := fresh "ACCc" in
      pose proof (FTInit_transport _ _ _ FTI MU ltac:(unfold P_A_FT_INIT; cbn; TAC)) as FI2;
      pose proof (ACONST_frame _ _ _ AC MU WM ltac:(eapply Forall_impl; [| exact FW]; intros iv (K & _ & _); exact K)) as AC2;
      pose proof (acc_transport_awin _ _ _ _ _ ACC MU FW) as ACC2
    end end.

