Ltac tab_s2f FTI AC ACC MU WM FW LN USPA TACW TAC64 TACLO CEIL TACSEP :=
  step; step; step; step;
  tab_now FTI AC ACC MU WM FW TACW;
  let S2 := fresh "S2" in
  pose proof s2f_spec as S2; unfold s2f_stmt, s2f_post, s2f_post_v, AS2F_STACK, X8_P_ftab_eq.AEQ_STACK, P_A_STRING_TO_FIELD, AG_FIELD_TABLE, wz in S2;
  lazymatch goal with
  | NB' : bytes_at _ ?mx ?p ?nbs, ST' : stk _ ?mx ?lo _, FTM' : FT ?mx, AC' : ACONST ?mx, ACC' : accessible ?mx ?p ?nlen, MI' : mem_inv _ ?mx
