      replace (Z_to_bv 64 nlen) with (Z_to_bv 64 (Z.of_nat (length nbs))) by (rewrite LN; reflexivity);
      callZc (S2 _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ F fc mx p lo nbs) (clear NB' ACC');
      [ exact NB' | exact FTM' | TAC64 | rewrite USPA; exact ST' | rewrite USPA; TACLO | exact CEIL | right; TACSEP | exact MI' | exact AC'
      | rewrite LN; exact ACC' | clear S2 ]
  end.

